-- The Begum Beauty: starter data. Run after schema.sql.
begin;

on conflict (id) do update set name = excluded.name, note = excluded.note, sort = excluded.sort;

on conflict (id) do update set name = excluded.name, blurb = excluded.blurb, image = excluded.image, sort = excluded.sort;

on conflict (id) do update set type = excluded.type, name = excluded.name, brand_id = excluded.brand_id, category_id = excluded.category_id, product_type = excluded.product_type, kind = excluded.kind, price = excluded.price, original_price = excluded.original_price, stock = excluded.stock, rating = excluded.rating, reviews = excluded.reviews, added_at = excluded.added_at, bestseller = excluded.bestseller, is_new = excluded.is_new, featured = excluded.featured, status = excluded.status, description = excluded.description, features = excluded.features, specs = excluded.specs, usage = excluded.usage, images = excluded.images, shades = excluded.shades, items = excluded.items, tone = excluded.tone, sku = excluded.sku;

delete from public.testimonials where sample;

on conflict (key) do update set title = excluded.title, text = excluded.text, cta = excluded.cta, link = excluded.link, image = excluded.image, active = excluded.active;

on conflict (key) do nothing;

commit;
