insert into public.products (id, type, name, brand_id, category_id, product_type, kind, price, original_price, stock, rating, reviews, added_at, bestseller, is_new, featured, status, description, features, specs, usage, images, shades, items, tone, sku) values
  ('velvet-matte-lipstick', 'product', 'Velvet Matte Lipstick', 'studio', 'lip-products', 'Lipstick', 'lipstick', 1850, 2200, 42, 4.8, 412, '2026-08-02', true, false, true, 'published', 'A soft-focus matte lipstick with full colour in one pass. Five shades selected to flatter light, medium and deep skin tones.', array['Full-coverage matte finish', 'Comfortable, non-drying feel', 'Bullet shaped for precise edges']::text[], '{"Finish":"Matte","Net weight":"3.8 g","Size":"Full size"}'::jsonb, 'Start at the centre of the lips and work outwards. Line first with a matching lip liner for a sharper edge.', array['/assets/images/products/velvet-matte-lipstick-1.jpg', '/assets/images/products/velvet-matte-lipstick-2.jpg', '/assets/images/products/velvet-matte-lipstick-3.jpg']::text[], '[{"name":"Rosewood","hex":"#A64F5E"},{"name":"Mulberry","hex":"#7E2C44"},{"name":"Terracotta Nude","hex":"#B8705C"},{"name":"Cocoa Kiss","hex":"#7A4438"},{"name":"Pink Petal","hex":"#D4848F"}]'::jsonb, '[]'::jsonb, 'blush', 'HM-VML-529'),
  ('satin-lip-gloss', 'product', 'Satin Shine Lip Gloss', 'velour', 'lip-products', 'Lip gloss', 'gloss', 1450, null, 30, 4.6, 188, '2026-09-12', false, true, false, 'published', 'A cushiony gloss with a satin shine and a sheer wash of colour. Wear alone or over lipstick.', array['High-shine, non-sticky', 'Doe-foot applicator']::text[], '{"Finish":"Glossy","Volume":"6 ml"}'::jsonb, 'Apply to the centre of the lips and press together.', array['/assets/images/products/satin-lip-gloss-1.jpg', '/assets/images/products/satin-lip-gloss-2.jpg', '/assets/images/products/satin-lip-gloss-3.jpg']::text[], '[{"name":"Pink Petal","hex":"#D4848F"},{"name":"Peach Silk","hex":"#E3A08C"},{"name":"Clear Glaze","hex":"#E8C9C2"}]'::jsonb, '[]'::jsonb, 'rose', 'HM-SLG-991'),
  ('sculpt-lip-liner', 'product', 'Sculpt Lip Liner', 'studio', 'lip-products', 'Lip liner', 'lipliner', 850, null, 64, 4.5, 233, '2026-06-20', false, false, false, 'published', 'A creamy pencil that defines and holds lipstick in place.', array['Creamy, long-wearing', 'Sharpenable']::text[], '{"Finish":"Satin","Net weight":"1.2 g"}'::jsonb, 'Outline the lips, then fill in lightly to help lipstick last.', array['/assets/images/products/sculpt-lip-liner-1.jpg', '/assets/images/products/sculpt-lip-liner-2.jpg', '/assets/images/products/sculpt-lip-liner-3.jpg']::text[], '[{"name":"Rosewood","hex":"#A64F5E"},{"name":"Mulberry","hex":"#7E2C44"},{"name":"Terracotta Nude","hex":"#B8705C"},{"name":"Cocoa Kiss","hex":"#7A4438"}]'::jsonb, '[]'::jsonb, 'nude', 'HM-SLL-782'),
  ('tinted-lip-balm', 'product', 'Tinted Lip Balm', 'lumiere', 'lip-products', 'Lip balm', 'lipstick', 990, null, 0, 4.4, 301, '2026-05-05', false, false, false, 'published', 'A nourishing balm with a soft hint of colour for everyday wear.', array['Sheer colour', 'Softening feel']::text[], '{"Finish":"Sheer","Net weight":"3.5 g"}'::jsonb, 'Apply as often as you like.', array['/assets/images/products/tinted-lip-balm-1.jpg', '/assets/images/products/tinted-lip-balm-2.jpg', '/assets/images/products/tinted-lip-balm-3.jpg']::text[], '[{"name":"Rose Tint","hex":"#B9606E"},{"name":"Berry Tint","hex":"#8A3A50"}]'::jsonb, '[]'::jsonb, 'rose', 'HM-TLB-919'),
  ('second-skin-foundation', 'product', 'Second Skin Foundation', 'lumiere', 'foundations-concealers', 'Foundation', 'foundation', 3400, 3900, 26, 4.7, 263, '2026-09-20', true, true, true, 'published', 'A breathable, medium-coverage foundation with a natural finish that holds up in heat and humidity.', array['Medium, buildable coverage', 'Natural finish', 'Six shades from porcelain to mocha']::text[], '{"Finish":"Natural","Coverage":"Medium, buildable","Volume":"30 ml"}'::jsonb, 'Shake well. Apply one pump with a brush or damp sponge, starting at the centre of the face.', array['/assets/images/products/second-skin-foundation-1.jpg', '/assets/images/products/second-skin-foundation-2.jpg', '/assets/images/products/second-skin-foundation-3.jpg']::text[], '[{"name":"Porcelain","hex":"#F2D9C4"},{"name":"Ivory Beige","hex":"#E7C6A8"},{"name":"Warm Sand","hex":"#D7AE88"},{"name":"Honey","hex":"#C4925F"},{"name":"Caramel","hex":"#A9774B"},{"name":"Mocha","hex":"#80553A"}]'::jsonb, '[]'::jsonb, 'nude', 'HM-SSF-705'),
  ('soft-blur-concealer', 'product', 'Soft Blur Concealer', 'lumiere', 'foundations-concealers', 'Concealer', 'concealer', 1950, null, 38, 4.6, 197, '2026-07-11', true, false, false, 'published', 'A creamy concealer that brightens under-eyes and covers spots without creasing.', array['Crease-resistant', 'Blendable cream texture']::text[], '{"Finish":"Satin","Volume":"6 ml"}'::jsonb, 'Dot under the eyes or on blemishes and tap to blend.', array['/assets/images/products/soft-blur-concealer-1.jpg', '/assets/images/products/soft-blur-concealer-2.jpg', '/assets/images/products/soft-blur-concealer-3.jpg']::text[], '[{"name":"Porcelain","hex":"#F2D9C4"},{"name":"Ivory Beige","hex":"#E7C6A8"},{"name":"Warm Sand","hex":"#D7AE88"},{"name":"Honey","hex":"#C4925F"},{"name":"Caramel","hex":"#A9774B"}]'::jsonb, '[]'::jsonb, 'sand', 'HM-SBC-170'),
  ('matte-fix-foundation', 'product', 'Matte Fix Foundation', 'velour', 'foundations-concealers', 'Foundation', 'foundation', 2750, null, 18, 4.4, 121, '2026-04-18', false, false, false, 'published', 'An oil-controlling foundation for combination and oily skin.', array['Full coverage', 'Soft-matte finish']::text[], '{"Finish":"Matte","Coverage":"Full","Volume":"30 ml"}'::jsonb, 'Apply with a brush, working in thin layers.', array['/assets/images/products/matte-fix-foundation-1.jpg', '/assets/images/products/matte-fix-foundation-2.jpg', '/assets/images/products/matte-fix-foundation-3.jpg']::text[], '[{"name":"Ivory Beige","hex":"#E7C6A8"},{"name":"Warm Sand","hex":"#D7AE88"},{"name":"Honey","hex":"#C4925F"},{"name":"Caramel","hex":"#A9774B"},{"name":"Mocha","hex":"#80553A"}]'::jsonb, '[]'::jsonb, 'sand', 'HM-MFF-451'),
  ('cheek-bloom-blush', 'product', 'Cheek Bloom Blush', 'studio', 'blush-highlighter', 'Blush', 'blush', 2100, null, 33, 4.7, 97, '2026-08-25', true, false, false, 'published', 'A finely milled powder blush that blends into a soft, natural flush.', array['Buildable colour', 'Silky powder']::text[], '{"Finish":"Satin","Net weight":"5 g"}'::jsonb, 'Sweep onto the apples of the cheeks and blend up towards the temples.', array['/assets/images/products/cheek-bloom-blush-1.jpg', '/assets/images/products/cheek-bloom-blush-2.jpg', '/assets/images/products/cheek-bloom-blush-3.jpg']::text[], '[{"name":"Dusty Rose","hex":"#C97A86"},{"name":"Apricot","hex":"#E09A7D"},{"name":"Plum Flush","hex":"#9E5465"}]'::jsonb, '[]'::jsonb, 'mauve', 'HM-CBB-570'),
  ('golden-hour-highlighter', 'product', 'Golden Hour Highlighter', 'atelier-nur', 'blush-highlighter', 'Highlighter', 'highlighter', 2350, 2800, 21, 4.8, 156, '2026-09-28', false, true, false, 'published', 'A luminous highlighter with a smooth, reflective finish for cheekbones and brow bones.', array['Pearlescent glow', 'Smooth, non-chalky']::text[], '{"Finish":"Luminous","Net weight":"6 g"}'::jsonb, 'Apply to the high points of the face with a fan or small tapered brush.', array['/assets/images/products/golden-hour-highlighter-1.jpg', '/assets/images/products/golden-hour-highlighter-2.jpg', '/assets/images/products/golden-hour-highlighter-3.jpg']::text[], '[{"name":"Champagne","hex":"#E9D0AE"},{"name":"Rose Gold","hex":"#E2B3A2"}]'::jsonb, '[]'::jsonb, 'sand', 'HM-GHH-830'),
  ('cream-blush-stick', 'product', 'Cream Blush', 'rangoli', 'blush-highlighter', 'Blush', 'concealer', 1650, null, 12, 4.3, 64, '2026-10-04', false, true, false, 'published', 'A sheer cream blush that melts into skin for a dewy look.', array['Dewy finish', 'Can be used on lips']::text[], '{"Finish":"Dewy","Volume":"7 ml"}'::jsonb, 'Dab onto cheeks and blend with fingertips.', array['/assets/images/products/cream-blush-stick-1.jpg', '/assets/images/products/cream-blush-stick-2.jpg', '/assets/images/products/cream-blush-stick-3.jpg']::text[], '[{"name":"Rose","hex":"#C46C7C"},{"name":"Coral","hex":"#E08770"}]'::jsonb, '[]'::jsonb, 'rose', 'HM-CBS-475'),
  ('desert-rose-palette', 'product', 'Desert Rose Eyeshadow Palette', 'maison-kohl', 'eye-makeup', 'Eyeshadow palette', 'palette', 4200, 4800, 15, 4.9, 356, '2026-07-30', true, false, true, 'published', 'Eight warm neutrals and roses in matte and shimmer finishes, from everyday to evening.', array['8 shades: 5 matte, 3 shimmer', 'Blendable, rich pigment']::text[], '{"Shades":"8","Net weight":"8 × 1.2 g"}'::jsonb, 'Use a fluffy brush for transition shades and a flat brush to pack shimmers onto the lid.', array['/assets/images/products/desert-rose-palette-1.jpg', '/assets/images/products/desert-rose-palette-2.jpg', '/assets/images/products/desert-rose-palette-3.jpg']::text[], '[]'::jsonb, '[]'::jsonb, 'nude', 'HM-DRP-638'),
  ('midnight-kohl-liner', 'product', 'Midnight Kohl Eyeliner', 'maison-kohl', 'eye-makeup', 'Eyeliner', 'eyeliner', 950, null, 80, 4.6, 520, '2026-03-14', true, false, false, 'published', 'A smudge-resistant kohl for tightlining, smoky eyes and precise wings.', array['Smudge-resistant', 'Soft, glide-on texture']::text[], '{"Finish":"Matte","Net weight":"1.1 g"}'::jsonb, 'Draw along the lash line and smudge if you like a softer look.', array['/assets/images/products/midnight-kohl-liner-1.jpg', '/assets/images/products/midnight-kohl-liner-2.jpg', '/assets/images/products/midnight-kohl-liner-3.jpg']::text[], '[{"name":"Jet Black","hex":"#1F1719"},{"name":"Espresso","hex":"#4A2E28"}]'::jsonb, '[]'::jsonb, 'stone', 'HM-MKL-509'),
  ('lift-define-mascara', 'product', 'Lift and Define Mascara', 'maison-kohl', 'eye-makeup', 'Mascara', 'mascara', 1750, null, 47, 4.4, 208, '2026-05-22', false, false, false, 'published', 'A lengthening mascara that separates and lifts lashes without clumping.', array['Lengthening', 'Curved brush']::text[], '{"Volume":"9 ml"}'::jsonb, 'Wiggle the wand from root to tip. Add a second coat while still wet.', array['/assets/images/products/lift-define-mascara-1.jpg', '/assets/images/products/lift-define-mascara-2.jpg', '/assets/images/products/lift-define-mascara-3.jpg']::text[], '[{"name":"Black","hex":"#1F1719"}]'::jsonb, '[]'::jsonb, 'ivory', 'HM-LDM-167'),
  ('precision-liquid-liner', 'product', 'Precision Liquid Liner', 'velour', 'eye-makeup', 'Eyeliner', 'eyeliner', 1250, 1500, 0, 4.5, 143, '2026-02-10', false, false, false, 'published', 'A fine felt-tip liner for crisp, long-wearing lines.', array['Felt tip', 'Quick-drying']::text[], '{"Volume":"0.6 ml"}'::jsonb, 'Draw short strokes along the lash line, then connect.', array['/assets/images/products/precision-liquid-liner-1.jpg', '/assets/images/products/precision-liquid-liner-2.jpg', '/assets/images/products/precision-liquid-liner-3.jpg']::text[], '[{"name":"Black","hex":"#1F1719"}]'::jsonb, '[]'::jsonb, 'stone', 'HM-PLL-462'),
  ('blur-primer', 'product', 'Pore Blur Primer', 'lumiere', 'face-makeup', 'Primer', 'primer', 2250, null, 29, 4.5, 176, '2026-06-02', false, false, false, 'published', 'A silky primer that softens the look of pores and helps makeup last longer.', array['Smoothing', 'Lightweight']::text[], '{"Volume":"30 ml"}'::jsonb, 'Apply a small amount after moisturiser, before foundation.', array['/assets/images/products/blur-primer-1.jpg', '/assets/images/products/blur-primer-2.jpg', '/assets/images/products/blur-primer-3.jpg']::text[], '[]'::jsonb, '[]'::jsonb, 'blush', 'HM-BP-350'),
  ('soft-glow-powder', 'product', 'Soft Glow Pressed Powder', 'studio', 'face-makeup', 'Powder', 'compact', 2650, null, 36, 4.5, 141, '2026-04-29', false, false, false, 'published', 'A finely milled pressed powder that sets makeup with a soft, skin-like finish.', array['Sets without caking', 'Portable compact with mirror']::text[], '{"Finish":"Soft matte","Net weight":"9 g"}'::jsonb, 'Press lightly over the T-zone and wherever you need to set makeup.', array['/assets/images/products/soft-glow-powder-1.jpg', '/assets/images/products/soft-glow-powder-2.jpg', '/assets/images/products/soft-glow-powder-3.jpg']::text[], '[{"name":"Porcelain","hex":"#F2D9C4"},{"name":"Ivory Beige","hex":"#E7C6A8"},{"name":"Warm Sand","hex":"#D7AE88"},{"name":"Honey","hex":"#C4925F"}]'::jsonb, '[]'::jsonb, 'sand', 'HM-SGP-448'),
  ('all-day-setting-spray', 'product', 'All-Day Setting Spray', 'atelier-nur', 'face-makeup', 'Setting spray', 'spray', 2450, null, 40, 4.6, 86, '2026-09-03', false, false, false, 'published', 'A fine mist that locks makeup in place through long days.', array['Fine, even mist', 'Refreshing feel']::text[], '{"Volume":"100 ml"}'::jsonb, 'Hold 20 cm from the face and mist in an X and T shape.', array['/assets/images/products/all-day-setting-spray-1.jpg', '/assets/images/products/all-day-setting-spray-2.jpg', '/assets/images/products/all-day-setting-spray-3.jpg']::text[], '[]'::jsonb, '[]'::jsonb, 'ivory', 'HM-ADSS-370'),
  ('translucent-setting-powder', 'product', 'Translucent Setting Powder', 'velour', 'face-makeup', 'Powder', 'powder', 2850, 3200, 9, 4.7, 219, '2026-08-14', true, false, false, 'published', 'A weightless loose powder to set concealer and control shine.', array['Universal translucent shade', 'Weightless']::text[], '{"Net weight":"15 g"}'::jsonb, 'Press onto skin with a puff, then dust off excess.', array['/assets/images/products/translucent-setting-powder-1.jpg', '/assets/images/products/translucent-setting-powder-2.jpg', '/assets/images/products/translucent-setting-powder-3.jpg']::text[], '[{"name":"Translucent","hex":"#EFE3D7"}]'::jsonb, '[]'::jsonb, 'stone', 'HM-TSP-201'),
  ('signature-brush-set', 'product', 'Signature Brush Set', 'studio', 'brushes-tools', 'Brush set', 'brushes', 3650, 4200, 22, 4.8, 134, '2026-07-08', false, false, true, 'published', 'Three essential brushes for face, cheeks and eyes, with soft synthetic bristles.', array['3 brushes', 'Soft synthetic bristles', 'Weighted handles']::text[], '{"Pieces":"3"}'::jsonb, 'Wash weekly with mild soap and lay flat to dry.', array['/assets/images/products/signature-brush-set-1.jpg', '/assets/images/products/signature-brush-set-2.jpg', '/assets/images/products/signature-brush-set-3.jpg']::text[], '[]'::jsonb, '[]'::jsonb, 'nude', 'HM-SBS-262'),
  ('blending-sponge', 'product', 'Blending Sponge', 'rangoli', 'brushes-tools', 'Beauty tool', 'sponge', 650, null, 120, 4.5, 388, '2026-01-20', false, false, false, 'published', 'A soft, bouncy sponge for seamless foundation and concealer.', array['Use damp or dry', 'Pointed tip for detail']::text[], '{"Pieces":"1"}'::jsonb, 'Dampen, squeeze out water and bounce over the skin.', array['/assets/images/products/blending-sponge-1.jpg', '/assets/images/products/blending-sponge-2.jpg', '/assets/images/products/blending-sponge-3.jpg']::text[], '[{"name":"Blush","hex":"#E8A6A9"}]'::jsonb, '[]'::jsonb, 'blush', 'HM-BS-646'),
  ('hydrating-rose-serum', 'product', 'Rosewater Hydrating Serum', 'lumiere', 'beauty-essentials', 'Skincare', 'serum', 3150, null, 24, 4.8, 174, '2026-10-08', false, true, false, 'published', 'A lightweight serum that leaves skin feeling hydrated and ready for makeup.', array['Lightweight', 'Absorbs quickly']::text[], '{"Volume":"30 ml"}'::jsonb, 'Apply 2–3 drops morning and evening before moisturiser.', array['/assets/images/products/hydrating-rose-serum-1.jpg', '/assets/images/products/hydrating-rose-serum-2.jpg', '/assets/images/products/hydrating-rose-serum-3.jpg']::text[], '[]'::jsonb, '[]'::jsonb, 'rose', 'HM-HRS-309'),
  ('overnight-repair-cream', 'product', 'Overnight Repair Cream', 'atelier-nur', 'beauty-essentials', 'Skincare', 'cream', 3800, null, 14, 4.6, 122, '2026-05-30', false, false, false, 'published', 'A rich night cream for soft, comfortable skin by morning.', array['Rich texture', 'For normal to dry skin']::text[], '{"Volume":"50 ml"}'::jsonb, 'Massage into face and neck at night.', array['/assets/images/products/overnight-repair-cream-1.jpg', '/assets/images/products/overnight-repair-cream-2.jpg', '/assets/images/products/overnight-repair-cream-3.jpg']::text[], '[]'::jsonb, '[]'::jsonb, 'ivory', 'HM-ORC-269'),
  ('makeup-remover-mist', 'product', 'Gentle Makeup Remover', 'rangoli', 'beauty-essentials', 'Skincare', 'spray', 1350, null, 55, 4.4, 92, '2026-03-03', false, false, false, 'published', 'A gentle remover that lifts makeup without tugging.', array['Gentle', 'Leaves no oily residue']::text[], '{"Volume":"150 ml"}'::jsonb, 'Apply to a cotton pad and sweep over the skin.', array['/assets/images/products/makeup-remover-mist-1.jpg', '/assets/images/products/makeup-remover-mist-2.jpg', '/assets/images/products/makeup-remover-mist-3.jpg']::text[], '[]'::jsonb, '[]'::jsonb, 'mauve', 'HM-MRM-462'),
  ('lash-curler-pro', 'product', 'Lash Curler', 'studio', 'brushes-tools', 'Beauty tool', 'eyeliner', 1100, null, 31, 4.3, 77, '2026-06-15', false, false, false, 'published', 'A precise curler with a gentle silicone pad.', array['Fits most eye shapes', 'Replacement pad included']::text[], '{"Pieces":"1"}'::jsonb, 'Clamp gently at the lash base for a few seconds.', array['/assets/images/products/lash-curler-pro-1.jpg', '/assets/images/products/lash-curler-pro-2.jpg', '/assets/images/products/lash-curler-pro-3.jpg']::text[], '[{"name":"Gold","hex":"#C8A27A"}]'::jsonb, '[]'::jsonb, 'stone', 'HM-LCP-790'),
  ('everyday-glow-deal', 'bundle', 'Everyday Glow Deal', 'studio', 'makeup-bundles', 'Makeup bundle', 'bundle', 4499, null, 18, 4.8, 90, '2026-09-01', true, false, true, 'published', 'Foundation, lipstick and mascara: the three products most people reach for every morning.', array['Curated by the Begum Beauty team', 'Each product is full size', 'Shades chosen at checkout via support chat']::text[], '{"Items":"3"}'::jsonb, '', array['/assets/images/products/everyday-glow-deal-1.jpg', '/assets/images/products/everyday-glow-deal-2.jpg', '/assets/images/products/second-skin-foundation-1.jpg']::text[], '[]'::jsonb, '[{"name":"Second Skin Foundation","image":"/assets/images/products/second-skin-foundation-1.jpg"},{"name":"Velvet Matte Lipstick","image":"/assets/images/products/velvet-matte-lipstick-1.jpg"},{"name":"Lift and Define Mascara","image":"/assets/images/products/lift-define-mascara-1.jpg"}]'::jsonb, 'blush', 'HM-EGD-114'),
